Add-Type -AssemblyName System.Drawing
$bmp = [System.Drawing.Bitmap]::FromFile((Resolve-Path 'images/chart.png'))
Write-Host ("size {0}x{1}" -f $bmp.Width, $bmp.Height)
foreach ($xc in @(195,335,520,700,845)) {
  for ($y = 40; $y -lt 500; $y++) {
    $c = $bmp.GetPixel($xc, $y)
    if ($c.R -gt 220 -and $c.G -gt 100 -and $c.G -lt 160 -and $c.B -lt 60) {
      Write-Host ("x={0} topY={1} rgb={2},{3},{4}" -f $xc, $y, $c.R, $c.G, $c.B)
      break
    }
  }
}
$bmp.Dispose()


--- tmp/measure2.ps1 ---
Add-Type -AssemblyName System.Drawing
$bmp = [System.Drawing.Bitmap]::FromFile((Resolve-Path 'images/chart.png'))
$w = $bmp.Width; $h = $bmp.Height
# orange columns
$runs = @()
$in = $false
for ($x = 0; $x -lt $w; $x++) {
  $found = $false
  for ($y = 40; $y -lt 500; $y++) {
    $c = $bmp.GetPixel($x, $y)
    if ($c.R -gt 220 -and $c.G -gt 100 -and $c.G -lt 160 -and $c.B -lt 60) { $found = $true; break }
  }
  if ($found -and -not $in) { $start = $x; $in = $true }
  if (-not $found -and $in) { $runs += ,@($start, $x - 1); $in = $false }
}
foreach ($r in $runs) {
  $xc = [int](($r[0] + $r[1]) / 2)
  for ($y = 40; $y -lt 500; $y++) {
    $c = $bmp.GetPixel($xc, $y)
    if ($c.R -gt 220 -and $c.G -gt 100 -and $c.G -lt 160 -and $c.B -lt 60) {
      Write-Host ("cols {0}-{1} center {2} topY {3}" -f $r[0], $r[1], $xc, $y)
      break
    }
  }
}
# gridline rows: light gray across plot area x=400
for ($y = 40; $y -lt 500; $y++) {
  $c = $bmp.GetPixel(400, $y)
  if ($c.R -ge 215 -and $c.R -le 235 -and $c.G -ge 215 -and $c.G -le 235 -and $c.B -ge 215 -and $c.B -le 235) {
    Write-Host ("grid y={0} rgb={1},{2},{3}" -f $y, $c.R, $c.G, $c.B)
  }
}
$bmp.Dispose()


